{
  "name": "opencode-answer-date",
  "version": "0.1.0",
  "description": "Appends a wall-clock timestamp line to every OpenCode V2 assistant reply",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/thejohnd0e/opencode-answer-date.git"
  },
  "homepage": "https://github.com/thejohnd0e/opencode-answer-date#readme",
  "type": "module",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "bun build src/index.ts --target=bun --format=esm --external=@opencode/plugin --outfile=dist/index.js",
    "prepublishOnly": "bun run build && bun run typecheck"
  },
  "dependencies": {},
  "peerDependencies": {
    "@opencode/plugin": ">=2.2.5"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.6",
    "@types/bun": "latest",
    "typescript": "^5.5.0"
  }
}

import { Plugin } from "@opencode/plugin"

const timeFmt = new Intl.DateTimeFormat("ru-RU", {
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
})
const dateFmt = new Intl.DateTimeFormat("ru-RU", {
  day: "2-digit",
  month: "2-digit",
  year: "numeric",
})

export default Plugin.define({
  id: "answer-date",
  async setup(ctx) {
    // Minimal injection: current time + one-line rule, ~25 tokens per model call.
    // The context hook runs immediately before dispatch, so the time is fresh
    // for every call, including tool-driven continuations.
    await ctx.session.hook("context", (event) => {
      const now = new Date()
      event.system.push({
        type: "text",
        text: `Current time: ${timeFmt.format(now)} · ${dateFmt.format(now)}. End the reply with this exact line as the last line: ⏱ ${timeFmt.format(now)} · ${dateFmt.format(now)}`,
      })
    })
  },
})
